import { Component } from '@angular/core';
import { FormControl, FormGroup } from '@angular/forms';
import { Message } from '../models/message.model';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
//import { OpenaiService } from '../services/openai.service';
import { HttpClientModule } from '@angular/common/http';



@Component({
  selector: 'app-tab2',
  templateUrl: 'tab2.page.html',
  styleUrls: ['tab2.page.scss']
})

export class Tab2Page{ 
    messages: Message[] = [
      {sender: 'me', content: 'Hola, como estas?'},
      {sender: 'bot', content: '¡Hola! Soy Fermín, tu asistente de compra virtual. Estoy aquí para ayudarte.'}
    ];

    form = new FormGroup({
    promt: new FormControl('')
})

loading: boolean = false;


constructor(
 //ESTO DA ERROR private openAi: OpenaiService
) { }

submit(){
  console.log(this.form.value);

  let promt = this.form.value.promt as string;

 // ====MSG USUARIO
 let userMsg: Message = { sender: 'me', content: promt }
 this.messages.push(userMsg);

 // ====MSG CHATBOT
 let botMsg: Message = { sender: 'bot', content: '' }
 this.messages.push(botMsg);


 this.form.reset();
 this.form.disable();

 this.loading = true;



/*
this.openAi.sendQuestion(promt).subscribe({
  next: (res: any) =>{

    console.log(res);
    this.loading = false;
  }, error: (error: any) =>{
    console.log(error);
  }

})
*/

  setTimeout(() =>{
    this.loading = false;
    this.typeText('Hoy tenemos en oferta, la Leche entera marca Pascual a 0,87€ el litro. El turrón de almendras Alacant a 4,17.')

    this.form.enable();
  }, 2000)


  }

  typeText(text: string){

    let textIndex = 0;
    let messagesLastIndex = this.messages.length - 1;

    let interval = setInterval(() => {
      if(textIndex < text.length){
        this.messages[messagesLastIndex].content += text.charAt(textIndex);
        textIndex++;
      }
      else{
        clearInterval(interval);
      }
    }, 15)
  }
}


<ion-content [fullscreen]="true">

  <ion-header collapse="condense" class="custom-header">
    <ion-toolbar class="custom-toolbar">
      <ion-title class="custom-title">Fermín</ion-title>
    </ion-toolbar>
  </ion-header>
  <!--
  <ion-list class="lista-mensajes">
    <app-mensaje-chat [mensaje]="mensaje1"></app-mensaje-chat>
    <app-mensaje-chat [mensaje]="mensaje2"></app-mensaje-chat>
    Puedes añadir más mensajes si es necesario 
  </ion-list>



  <ion-input class="formulario_chat" placeholder="Escribe tu mensaje..." ></ion-input>
  <button class="boton_enviar_mensaje">
    <ion-icon name="arrow-forward-circle-outline"></ion-icon>
  </button>
-->

   <ion-item lines="none" [ngClass]="{bot: m.sender !== 'me'}"class="chat-item" *ngFor="let m of messages; index as i">
    <ion-badge slot="start" [color]="m.sender == 'me' ? 'success':  'tertiary'" mode="ios">
      <ion-icon class="chat-icon" [src]=" m.sender == 'me' ? 'assets/user.svg' : 'assets/bot.svg'" ></ion-icon>
    </ion-badge>
      <ion-label class="ion-text-wrap">
      {{m.content}}
      <ion-spinner *ngIf="loading && (i+1 == messages.length)" color="tertiary" name="dots"></ion-spinner>
    </ion-label>
</ion-item>

</ion-content>



<ion-footer class="ion-padding">

  <form [formGroup]="form" (ngSubmit)="submit()" (keyup.enter)="submit()">

    <ion-item class="text-box-item">
      <ion-textarea formControlName="promt" auto-grow="true" placeholder="Escribe tu pregunta..."></ion-textarea>

      <ion-buttons slot="end">
      <ion-button>
        <ion-icon name="send"></ion-icon>
      </ion-button>
      </ion-buttons>
    </ion-item>

  </form>


</ion-footer>
